function evaluateFunction(funcText, x) {
  // Extract expression after "f(x)=" or "y=" etc.
  const match = funcText.match(/=\s*(.+)/);
  if (!match) throw new Error("Invalid function format. Expected 'f(x)=...'");

  let expr = match[1].trim();

  // Replace implicit multiplication (e.g., "2x" -> "2*x")
  expr = expr.replace(/(\d)([a-zA-Z])/g, '$1*$2');
  expr = expr.replace(/([a-zA-Z])(\d)/g, '$1*$2');

  // Safely evaluate with x in scope
  const fn = new Function('x', `"use strict"; return (${expr});`);
  return fn(x);
}

// Example usage:
console.log(evaluateFunction("f(x)=2x+3", 5)); // 13
console.log(evaluateFunction("f(x)=x^2+1", 3)); // Note: use x**2 for powers
```

**Note:** This uses `new Function()` which evaluates arbitrary code. Only use with trusted input. For production, consider a proper math parser like [mathjs](https://mathjs.org/). Also, JavaScript uses `**` not `^` for exponentiation; add `.replace(/\^/g, '**')` if you need caret support.

